# Prova nel browser: python3 test/browser.py (con un server locale sulla cartella dell'app, porta 8766)
from playwright.sync_api import sync_playwright
with sync_playwright() as p:
    b = p.chromium.launch(executable_path='/usr/bin/google-chrome'); ctx = b.new_context(viewport={'width': 430, 'height': 900}); pg = ctx.new_page()
    errs = []; pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.goto('http://localhost:8766/index.html?u=1017,1005'); pg.wait_for_timeout(1200); pg.evaluate("window.print=()=>{}")
    print('da URL', pg.locator('.cgv').count(), pg.url)
    pg.fill('#cgU', 'acetone'); pg.wait_for_timeout(300); print('ricerca nome', pg.locator('#cgRes .res').count(), pg.inner_text('#cgRes')[:80])
    pg.locator('#cgRes .res').first.click(); pg.wait_for_timeout(200)
    for u in ['1789', '1824', '2683']:
        pg.fill('#cgU', u); pg.wait_for_timeout(150); pg.press('#cgU', 'Enter'); pg.wait_for_timeout(150)
    pg.fill('#cgU', '9999'); pg.wait_for_timeout(150); print('9999:', pg.inner_text('#cgRes'))
    print('avviso 7.2.3.4', pg.locator('input[data-k=subTab]').count())
    pg.locator('input[data-k=subTab]').check(); pg.wait_for_timeout(200)
    t = pg.inner_text('#cgRis'); print(len(t), 'BAD' if ('undefined' in t or 'NaN' in t) else 'ok')
    pg.locator('#cgLista input[data-k=lq]').nth(1).check(); pg.wait_for_timeout(200)
    pg.locator('#cgLista select[data-k=unita]').nth(0).select_option('aperta'); pg.wait_for_timeout(200)
    print('tabella e dettaglio nascosti', pg.locator('table.bordo').count() == 0, pg.locator('#cgRis details summary:has-text("UN 1017 /")').count() == 0)
    pg.click('#cgPrint'); print('report senza dettaglio', 'Dettaglio per coppia' not in pg.text_content('#report'))
    pg.click('#btnCoppie'); pg.wait_for_timeout(200); print('dettaglio visibile', pg.locator('#cgRis details summary:has-text("UN 1017 /")').count() > 0)
    pg.click('#cgPrint'); print('report con dettaglio', 'Dettaglio per coppia' in pg.text_content('#report'))
    pg.click('#btnBordo'); pg.wait_for_timeout(200)
    print('bordo CC/CO', pg.locator('table.bordo tr').count(), 'chiuso contro aperto' in pg.inner_text('#cgRis'))
    pg.click('#cgPrint'); print('report con tabella', pg.locator('#report table.bordo').count() == 1)
    pg.click('#btnBordo'); pg.wait_for_timeout(200); pg.click('#cgPrint'); print('report senza tabella', pg.locator('#report table.bordo').count() == 0)
    pg.click('#btnBordo'); pg.wait_for_timeout(200)
    pg.select_option('#nvTipo', 'senza'); pg.wait_for_timeout(200); print('hatchless', '7.4.3.3' in pg.inner_text('#cgRis'), pg.is_visible('#nvCop'))
    pg.select_option('#nvTipo', 'chiuse'); pg.select_option('#nvCop', 'nogutter'); pg.check('#nvVecchia'); pg.wait_for_timeout(200)
    print('gutterbar', '7.4.2.2.2' in pg.inner_text('#cgRis'), 'vecchia', '7.4.2.4.1' in pg.inner_text('#cgRis'))
    pg.fill('#cgRif', 'M/V Prova, container ABCU1234567')
    pg.screenshot(path='/tmp/app.png', full_page=True)
    pg.click('#cgPrint'); rep = pg.inner_text('#report'); print('REP', len(rep), 'BAD' if 'undefined' in rep else 'ok', 'scelta utente' if "scelta dell'utente" in rep else 'NO SCELTA')
    pg.emulate_media(media='print'); pg.pdf(path='/tmp/report.pdf', format='A4'); pg.emulate_media(media='screen')
    pg.reload(); pg.wait_for_timeout(1000); print('persist', pg.locator('.cgv').count(), 'nave', pg.input_value('#nvCop'))
    pg.goto('http://localhost:8766/index.html?u=1489,2014,0081,0339'); pg.wait_for_timeout(800)
    print('legenda righe', pg.locator('ul.leg li').count(), 'coppie segnalate', pg.locator('ul.segnalate > li').count())
    pg.locator('h3:has-text("Matrice")').evaluate('e=>e.scrollIntoView()'); pg.locator('#cgRis').screenshot(path='/tmp/segn.png')
    pg.click('#cgPrint'); print('report segnalate', pg.locator('#report ul.segnalate > li').count())
    # v1.8: ro-ro e carico generale
    pg.evaluate("localStorage.removeItem('carico')"); pg.goto('http://localhost:8766/index.html?u=1203,1017,1005'); pg.wait_for_timeout(800)
    if pg.locator('#btnBordo').get_attribute('aria-pressed') != 'true': pg.click('#btnBordo'); pg.wait_for_timeout(150)
    pg.select_option('#nvTipo', 'roro'); pg.wait_for_timeout(200)
    print('roro', '7.5.3.2' in pg.text_content('#cgRis'), pg.is_visible('#nvPax'), not pg.is_visible('#nvCop'), pg.locator('table.bordo th').count() == 5)
    pg.select_option('#nvTipo', 'generale'); pg.wait_for_timeout(200)
    print('colli disponibili', pg.locator('#cgLista select[data-k=unita] option[value=colli]').count())
    pg.locator('#cgLista select[data-k=unita]').nth(0).select_option('colli'); pg.wait_for_timeout(200)
    txt = pg.text_content('#cgRis'); print('generale', '7.6.3' in txt, pg.locator('table.bordo th').count() == 3, '7.6.2.6.1' in txt)
    pg.select_option('#nvPax', 'pax'); pg.wait_for_timeout(200); print('passeggeri', 'navi passeggeri' in pg.text_content('#cgRis'))
    pg.locator('h3:has-text("A bordo")').evaluate('e=>e.scrollIntoView()'); pg.locator('#cgRis').screenshot(path='/tmp/gen.png')
    pg.click('#cgPrint'); rep = pg.text_content('#report'); print('report generale', 'nave da carico generale' in rep, 'undefined' not in rep)
    pg.select_option('#nvTipo', 'roro'); pg.wait_for_timeout(200); pg.click('#cgPrint'); rep = pg.text_content('#report'); print('report roro', 'nave ro-ro' in rep and 'undefined' not in rep)
    pg.select_option('#nvPax', 'carico'); pg.select_option('#nvTipo', 'chiuse')
    print('ERR', errs); b.close()
